import {renderPixels} from './editor-engine.js';
// Tool semantics are generated by the real renderer, not assumed from another editor.
export function editorControlReference() {
  const patches=new Uint8ClampedArray([64,64,64,255,128,128,128,255,220,220,220,255]);
  const trials=[{exposure:.5},{exposure:1},{shadows:25},{highlights:-30},{warmth:-15},{warmth:-35},{warmth:-50},{warmth:-65,tint:14},{tint:25},{tint:-25}];
  return trials.map(settings=>{
    const output=renderPixels(patches,3,1,settings);
    return {settings,encodedRGB:[0,1,2].map(i=>Array.from(output.slice(i*4,i*4+3)))};
  });
}
export function controlReferencePrompt() {
  return `当前编辑器的实际响应标定（不是 Lightroom 的开尔文数值）：输入中性灰 RGB 分别为 [64,64,64]、[128,128,128]、[220,220,220]，各参数单独作用后的编码 RGB 为 ${JSON.stringify(editorControlReference())}。曝光以线性光 EV 计算，+1 不会把编码亮度翻倍；warmth/tint 是相对白平衡增益。warmth 正值更暖、负值更冷；tint 正值减绿／向洋红，负值减洋红／向绿。要校正绿偏应增加 tint，不能给负的 tint 来增加绿偏；修正洋红偏则相反。-15 warmth 只是很轻的降暖。根据可见色偏与目标选择足够但不过度的强度，强黄绿偏可比较 -35/+8 与 -65/+14 两档 warmth/tint 试片，选择已有效而自然的力度，并检查是否也偏绿而需要 tint。不要因保留原片而使建议对明确缺陷几乎无效，不要以提亮替代白平衡；这些灰卡参照只说明工具强度，不能证明照片中的墙或衣物本来应是灰色。被剪切的色彩与高光不能恢复。`;
}

// Only reject an explicit correction goal whose nonzero tint moves the other way.
// This does not judge whether a scene is green, or prohibit a deliberate color style.
export function assertTintCorrectionDirection(target,tint) {
  if(!Number.isFinite(tint)||!tint)return;
  const text=String(target||''),correct=/(消除|校正|纠正|修正|减轻|减少|减弱|去除|中和)[^。；！？\n]{0,12}?(偏绿|绿偏|绿色色偏|偏洋红|洋红偏|偏品红|品红偏)/g;
  for(const match of text.matchAll(correct)) {
    if(/(?:不|无需|不必|不要)$/.test(text.slice(0,match.index)))continue;
    const green=['偏绿','绿偏','绿色色偏'].includes(match[2]);
    if(green&&tint<0||!green&&tint>0)throw new Error('色调方向与色偏校正目标相反：tint 正值减绿，负值减洋红。请重新检查依据与参数。');
  }
}
